// The next two days as one long sky, left to right: each hour's slice is the
// color the sky will be then (night, dawn, day, dusk, greyed by its clouds),
// the temperature is drawn across it as a line, and the rain hangs from the
// top like curtains, as long as the rain is heavy.
import { kindOf, wordsFor, degrees, mix, placeClock, hourIndex, dayIndex, WEEKDAYS, two } from './weather'

// Sky color by minutes from the nearest sunrise or sunset: - night, + day.
const SKY: [number, string][] = [
  [-130, '#0a1230'],
  [-70, '#1b2350'],
  [-25, '#45406e'],
  [0, '#7d5a72'],
  [25, '#b08070'],
  [70, '#7f9cc2'],
  [130, '#4f86c4'],
]

function skyAt(minutes: number) {
  if (minutes <= SKY[0][0]) return SKY[0][1]
  for (let i = 1; i < SKY.length; i++) {
    if (minutes <= SKY[i][0]) {
      return mix(SKY[i - 1][1], SKY[i][1], (minutes - SKY[i - 1][0]) / (SKY[i][0] - SKY[i - 1][0]))
    }
  }
  return SKY[SKY.length - 1][1]
}

// The look. On an LCD the sky in color. On e-paper with no color (1-bit, or
// 16 greys) black on white: no sky, the nights a black bar along the hours,
// the rain an outlined curtain, no grey anywhere. On color e-paper the same
// in the Spectra inks, so they print solid. The Contrast setting can choose
// either.
type Look = 'color' | 'mono' | 'inks'
function lookOf(app: FrameOSApp): Look {
  const mode = app.state.contrast || 'auto'
  if (mode === 'high' || (mode === 'auto' && app.frame.color === false)) return 'mono'
  if (mode === 'color') return 'color'
  return app.frame.paper ? 'inks' : 'color'
}
// The six inks of a Spectra panel, as the colors that come through its fit and
// dither as one ink each (tried in the bench's simulator of the panel).
const INK = { black: '#000000', white: '#ffffff', yellow: '#ffff00', red: '#800000', blue: '#0000ff', green: '#008000' }

// A smooth line through points (Catmull-Rom as cubic Béziers).
function smooth(points: number[][], floor = -Infinity) {
  let d = `M${points[0][0].toFixed(1)} ${points[0][1].toFixed(1)}`
  for (let i = 0; i < points.length - 1; i++) {
    const p0 = points[Math.max(0, i - 1)]
    const p1 = points[i]
    const p2 = points[i + 1]
    const p3 = points[Math.min(points.length - 1, i + 2)]
    const c1x = p1[0] + (p2[0] - p0[0]) / 6
    const c1y = Math.max(floor, p1[1] + (p2[1] - p0[1]) / 6)
    const c2x = p2[0] - (p3[0] - p1[0]) / 6
    const c2y = Math.max(floor, p2[1] - (p3[1] - p1[1]) / 6)
    d += ` C${c1x.toFixed(1)} ${c1y.toFixed(1)} ${c2x.toFixed(1)} ${c2y.toFixed(1)} ${p2[0].toFixed(1)} ${p2[1].toFixed(1)}`
  }
  return d
}

export function get(app: FrameOSApp, context: FrameOSContext) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const weather = app.config.weather || {}
  if (!weather.current || !weather.hourly) {
    throw new Error(weather.error || 'No weather yet')
  }
  const look = lookOf(app)
  const paper = look !== 'color'
  const ink = paper ? INK.black : '#ffffff'
  const ground = paper ? INK.white : '#000000'
  const twelve = app.config.clock === '12h'
  const offset = weather.offset || 0
  const now = Date.now()
  const hourly = weather.hourly
  const daily = weather.daily
  const first = Math.max(0, hourIndex(hourly, now))
  const portrait = H > W
  // A round panel shows only the circle inside its square: a day across it,
  // the words centred in the arcs above and below (docs/scene-guide.md).
  const round = context.round === true
  const radius = Math.min(W, H) / 2
  // Half the circle's width at a height: what a row of text there may use.
  const halfChord = (y: number) => Math.sqrt(Math.max(0, radius * radius - (y - H / 2) * (y - H / 2)))
  const inCircle = (px: number, py: number, margin: number) => Math.abs(px - W / 2) <= halfChord(py) - margin
  // A tall screen has room for a day and a half, a wide one for two days.
  const wanted = round ? 24 : portrait ? 36 : 48
  const count = Math.min(wanted, hourly.temperature.length - first)
  const hours = []
  for (let k = 0; k < count; k++) hours.push(first + k)
  const u = Math.min(W, H) / 100
  // Nothing a person reads under 10 px (an hour on a 2.8").
  const fs = (k: number) => Math.max(u * k, 10)
  // A line on paper is two pixels at least: a thinner one is grey at its
  // edges, and grey is what e-paper cannot print.
  const lw = (k: number) => (paper ? Math.max(u * k, 2) : u * k)
  // Words over the chart: on paper with a ring of the paper around them, so a
  // line or a midnight under them does not cut them.
  const words = (x: number, y: number, size: number, text: string, props: Record<string, any> = {}) =>
    paper ? (
      <g>
        <text x={x} y={y} fontFamily="FiraGO" fontSize={size} {...props} fill={ground} stroke={ground} strokeWidth={size * 0.28} strokeLinejoin="round" opacity={1}>
          {text}
        </text>
        <text x={x} y={y} fontFamily="FiraGO" fontSize={size} {...props} fill={ink} opacity={1}>
          {text}
        </text>
      </g>
    ) : (
      <text x={x} y={y} fontFamily="FiraGO" fontSize={size} fill={ink} {...props}>
        {text}
      </text>
    )

  // Time runs left to right, from now.
  const left = 0
  const right = W
  const span = count * 3600000
  const x = (ms: number) => left + ((ms - now) / span) * (right - left)
  const hourMid = (i: number) => hourly.start + i * 3600000 + 1800000

  // Each hour's sky.
  const minutesFromSun = (ms: number) => {
    const d = Math.max(0, Math.min(daily.sunrise.length - 1, dayIndex(daily, ms)))
    const rise = daily.sunrise[d]
    const set = daily.sunset[d]
    if (ms >= rise && ms <= set) return Math.min(ms - rise, set - ms) / 60000
    const nextRise = daily.sunrise[d + 1] ?? rise + 86400000
    const prevSet = daily.sunset[d - 1] ?? set - 86400000
    return -Math.min(Math.abs(ms - (ms < rise ? prevSet : set)), Math.abs((ms < rise ? rise : nextRise) - ms)) / 60000
  }
  // A stop every twenty minutes, so dawn and dusk blend; the cloud cover is
  // averaged over three hours, so a passing cloud does not stripe the sky.
  const cloudAt = (ms: number) => {
    const i = Math.max(0, Math.min(hourly.cloud.length - 1, hourIndex(hourly, ms)))
    let sum = 0
    let n = 0
    for (let k = i - 1; k <= i + 1; k++) {
      if (k >= 0 && k < hourly.cloud.length && hourly.cloud[k] != null) {
        sum += hourly.cloud[k]
        n++
      }
    }
    return n ? sum / n / 100 : 0.5
  }
  const stops = []
  for (let ms = now; ms <= now + count * 3600000; ms += 1200000) {
    const minutes = minutesFromSun(ms)
    const grey = minutes > 0 ? '#6c7682' : '#1c212b'
    stops.push({ offset: (x(ms) - left) / (right - left), color: mix(skyAt(minutes), grey, cloudAt(ms) * 0.72) })
  }

  // Bands for the words: top for the header, bottom for the hours.
  const top = round ? H * 0.37 : H * (portrait ? 0.22 : 0.27)
  const bottom = round ? H * 0.72 : H * 0.84
  const curveTop = top + (bottom - top) * 0.32
  const curveBottom = bottom - (bottom - top) * 0.1

  // The temperature line.
  const temps = hours.map((i) => hourly.temperature[i])
  const tMax = Math.max(...temps)
  const tMin = Math.min(...temps)
  const tSpan = Math.max(weather.fahrenheit ? 8 : 4, tMax - tMin)
  const ty = (t: number) => curveBottom - ((t - tMin) / tSpan) * (curveBottom - curveTop)
  // The line starts at the left edge with the hourly forecast's own
  // temperature at this moment (between two hours' middles), so it does not
  // jump from the current reading to the forecast at the edge.
  const nowAt = (now - hourly.start - 1800000) / 3600000
  const k0 = Math.max(0, Math.min(hourly.temperature.length - 2, Math.floor(nowAt)))
  const tNow0 = hourly.temperature[k0] + (hourly.temperature[k0 + 1] - hourly.temperature[k0]) * Math.max(0, Math.min(1, nowAt - k0))
  const tNow = isFinite(tNow0) ? tNow0 : (weather.current.temperature ?? temps[0])
  const points = [[left, ty(tNow)]]
  for (const i of hours) {
    const px = x(hourMid(i))
    if (px > left + 1) points.push([px, ty(hourly.temperature[i])])
  }
  points.push([right, ty(temps[temps.length - 1])])
  const line = smooth(points)
  const area = `${line} L${right} ${H} L${left} ${H} Z`

  // Rain curtains from the top of the chart.
  const unitScale = weather.units.precipitation === 'in' ? 25.4 : 1
  const rainMax = Math.max(3 / unitScale, ...hours.map((i) => hourly.precipitation[i] ?? 0))
  const curtainLength = (bottom - top) * 0.55
  const slot = (right - left) / count
  // One curtain along the top, its hem as low as the rain is heavy, with
  // streaks of rain inside it.
  const hem = [[left, top]]
  const streaks = []
  const dots = []
  for (const i of hours) {
    const amount = hourly.precipitation[i] ?? 0
    const chance = hourly.rainChance[i] ?? 0
    const cx = x(hourMid(i))
    const wet = amount >= 0.05 / unitScale
    const length = wet ? Math.max(u * 2.5, curtainLength * Math.sqrt(amount / rainMax)) : 0
    hem.push([cx, top + length])
    if (wet && kindOf(hourly.code[i]) === 'snow') {
      for (let k = 0; k < 4; k++) {
        streaks.push(<circle cx={cx + (k % 2 ? 0.25 : -0.25) * slot} cy={top + length * (0.2 + k * 0.2)} r={u * 0.45} fill={look === 'mono' ? ink : '#ffffff'} opacity={paper ? 1 : 0.7} />)
      }
    } else if (wet) {
      for (let k = 0; k < 3; k++) {
        const sx = cx + (k - 1) * slot * 0.3
        streaks.push(<line x1={sx} y1={top + u} x2={sx - u * 0.6} y2={top + length * (0.75 + 0.1 * k)} stroke={look === 'mono' ? ink : '#ffffff'} strokeWidth={lw(0.22)} strokeLinecap="round" opacity={paper ? 1 : 0.35} />)
      }
    } else if (chance >= 25) {
      dots.push(<circle cx={cx} cy={top + u * 1.6} r={Math.max(u * 0.45, 1.5)} fill={look === 'inks' ? INK.blue : ink} opacity={paper ? 1 : 0.35 + chance / 250} />)
    }
  }
  hem.push([right, hem[hem.length - 1][1]])
  const anyRain = hem.some((p) => p[1] > top)
  const curtain = anyRain ? `${smooth(hem, top)} L${right} ${top} Z` : ''

  // Midnights, day names and hour marks.
  const marks = []
  const firstHour = placeClock(hourly.start + first * 3600000, offset).getUTCHours()
  // An hour label every three hours where they have the room, else six.
  const labelEvery = portrait || (W / count) * 3 < fs(3) * 2.6 ? 6 : 3
  for (const i of hours.concat([first + count])) {
    const at = hourly.start + i * 3600000
    if (at <= now) continue
    const hour = (firstHour + (i - first)) % 24
    const hx = x(at)
    if (hour === 0) {
      marks.push(<line x1={hx} y1={top - u * 2} x2={hx} y2={bottom + u * 2} stroke={ink} strokeWidth={lw(0.25)} opacity={paper ? 1 : 0.45} />)
      const name = WEEKDAYS[placeClock(at, offset).getUTCDay()]
      // Keep the name on the screen near the right edge.
      const nameSize = fs(3.6)
      const fits = round
        ? hx + u * 1.2 + name.length * nameSize * 0.56 < W / 2 + halfChord(top - u * 2.4) - 12
        : hx + u * 1.2 + name.length * nameSize * 0.56 < W - u * 2
      marks.push(words(fits ? hx + u * 1.2 : hx - u * 1.2, top - u * 2.4, nameSize, name, { fontWeight: 600, textAnchor: fits ? 'start' : 'end' }))
    } else if (hour % labelEvery === 0 && (!round || inCircle(hx, bottom + u * 4.6, 12 + u * 2))) {
      marks.push(<line x1={hx} y1={bottom} x2={hx} y2={bottom + u * 1.2} stroke={ink} strokeWidth={lw(0.25)} opacity={paper ? 1 : 0.6} />)
      const label = twelve ? (hour % 12 || 12) + (hour < 12 ? 'a' : 'p') : two(hour)
      const size = fs(3)
      marks.push(
        <text x={hx} y={bottom + u * 1.6 + size} fontFamily="FiraGO" fontWeight={paper ? 600 : 400} fontSize={size} fill={ink} opacity={paper ? 1 : 0.85} textAnchor="middle">
          {label}
        </text>,
      )
    }
  }

  // Temperatures on the line: every few hours, and the highs and lows bigger.
  const labels = []
  const every = portrait ? 6 : 4
  const extremes = new Set<number>()
  for (let k = 1; k < count - 1; k++) {
    const t = temps[k]
    const isMax = t >= temps[k - 1] && t > temps[k + 1] && t >= Math.max(...temps.slice(Math.max(0, k - 8), k + 9))
    const isMin = t <= temps[k - 1] && t < temps[k + 1] && t <= Math.min(...temps.slice(Math.max(0, k - 8), k + 9))
    if ((isMax || isMin) && !extremes.has(k - 1) && !extremes.has(k - 2)) extremes.add(k)
  }
  for (let k = 2; k < count - 1; k++) {
    const extreme = extremes.has(k)
    const nearExtreme = !extreme && (extremes.has(k - 1) || extremes.has(k + 1) || extremes.has(k - 2) || extremes.has(k + 2))
    if (!extreme && (k % every !== 0 || nearExtreme)) continue
    const cx = x(hourMid(hours[k]))
    const cy = ty(temps[k])
    labels.push(<circle cx={cx} cy={cy} r={Math.max(u * (extreme ? 0.9 : 0.6), 2)} fill={ink} />)
    labels.push(words(cx, cy - u * 2.2, extreme ? fs(4.4) : fs(3.2), degrees(temps[k]), { fontWeight: extreme || paper ? 600 : 400, textAnchor: 'middle', opacity: extreme ? 1 : 0.85 }))
  }

  // Sunrise and sunset under the hours.
  const suns = []
  for (let d = 0; d < daily.sunrise.length; d++) {
    for (const [ms, up] of [[daily.sunrise[d], true], [daily.sunset[d], false]] as [number, boolean][]) {
      if (ms <= now || ms >= now + span) continue
      const sx = x(ms)
      // A sun too near either edge to draw whole is left out.
      if (sx < u * 2.5 || sx > W - u * 2.5) continue
      const sy = bottom + u * 6.5 + fs(3) * 1.05
      // On a round panel, only one the circle shows with its time.
      if (round && !inCircle(sx, sy, 12 + u * 2.2)) continue
      const sunFill = look === 'mono' ? (up ? ink : ground) : look === 'inks' ? (up ? INK.yellow : INK.red) : up ? '#f6cf6d' : '#ef9663'
      suns.push(<path d={`M${sx - u * 1.4} ${sy} A${u * 1.4} ${u * 1.4} 0 0 1 ${sx + u * 1.4} ${sy} Z`} fill={sunFill} stroke={paper ? ink : 'none'} strokeWidth={lw(0.3)} />)
      suns.push(<line x1={sx - u * 2.2} y1={sy} x2={sx + u * 2.2} y2={sy} stroke={ink} strokeWidth={lw(0.25)} opacity={paper ? 1 : 0.7} />)
      // Its time beside it, where there is room for it.
      // (On a round panel, on its left where the circle leaves no room right.)
      const leftOfIt = round && !inCircle(sx + u * 12, sy, 12)
      if (!portrait && (round ? !leftOfIt || inCircle(sx - u * 12, sy, 12) : sx + u * 3 + fs(2.8) * 2.8 < W)) {
        const d0 = placeClock(ms, offset)
        const h = d0.getUTCHours()
        const text = twelve ? `${h % 12 || 12}:${two(d0.getUTCMinutes())}` : `${two(h)}:${two(d0.getUTCMinutes())}`
        suns.push(
          leftOfIt ? (
            <text x={sx - u * 3} y={sy + u * 0.4} fontFamily="FiraGO" fontSize={fs(3)} fill={ink} opacity={paper ? 1 : 0.8} textAnchor="end">
              {text}
            </text>
          ) : (
            <text x={sx + u * 3} y={sy + u * 0.4} fontFamily="FiraGO" fontSize={round ? fs(3) : fs(2.8)} fill={ink} opacity={paper ? 1 : 0.8}>
              {text}
            </text>
          ),
        )
      }
    }
  }

  // On paper the nights are a black bar along the hours.
  const nights = []
  if (paper) {
    for (let d = -1; d < daily.sunrise.length; d++) {
      const from = Math.max(now, daily.sunset[d] ?? daily.sunrise[0] - 86400000 + (daily.sunset[0] - daily.sunrise[0]))
      const to = Math.min(now + span, daily.sunrise[d + 1] ?? from)
      if (to > from) nights.push(<rect x={x(from)} y={bottom} width={x(to) - x(from)} height={Math.max(u * 1.3, 3)} fill={ink} />)
    }
  }

  const current = weather.current
  const totalRain = hours.reduce((sum, i) => sum + (hourly.precipitation[i] ?? 0), 0)
  const snowy = hours.filter((i) => kindOf(hourly.code[i]) === 'snow').length > hours.filter((i) => (hourly.precipitation[i] ?? 0) > 0).length / 2
  const rainText = totalRain >= 0.1 / unitScale
    ? `${weather.units.precipitation === 'in' ? totalRain.toFixed(2) : totalRain < 10 ? totalRain.toFixed(1) : Math.round(totalRain)} ${weather.units.precipitation} of ${snowy ? 'snow (as water)' : 'rain'} in ${count} hours`
    : `Dry for the next ${count} hours`

  return (
    <svg viewBox={`0 0 ${W} ${H}`} width={W} height={H}>
      <linearGradient id="sky" gradientUnits="userSpaceOnUse" x1={left} y1="0" x2={right} y2="0">
        {stops.map((s) => <stop offset={s.offset.toFixed(4)} stopColor={s.color} />)}
      </linearGradient>
      <linearGradient id="depth" gradientUnits="userSpaceOnUse" x1="0" y1="0" x2="0" y2={H}>
        <stop offset="0" stopColor="#000000" stopOpacity="0.35" />
        <stop offset="0.45" stopColor="#000000" stopOpacity="0" />
        <stop offset="0.8" stopColor="#000000" stopOpacity="0.05" />
        <stop offset="1" stopColor="#000000" stopOpacity="0.4" />
      </linearGradient>
      <linearGradient id="curtain" gradientUnits="userSpaceOnUse" x1="0" y1={top} x2="0" y2={top + curtainLength}>
        <stop offset="0" stopColor="#dcecff" stopOpacity="0.85" />
        <stop offset="1" stopColor="#dcecff" stopOpacity="0.15" />
      </linearGradient>
      <linearGradient id="ground" gradientUnits="userSpaceOnUse" x1="0" y1={curveTop} x2="0" y2={H}>
        <stop offset="0" stopColor="#ffffff" stopOpacity="0.22" />
        <stop offset="1" stopColor="#ffffff" stopOpacity="0.04" />
      </linearGradient>
      {paper ? <rect width={W} height={H} fill={ground} /> : <rect width={W} height={H} fill="url(#sky)" />}
      {paper ? null : <rect width={W} height={H} fill="url(#depth)" />}
      {anyRain && !paper ? <path d={curtain} fill="url(#curtain)" /> : null}
      {anyRain && paper ? <path d={curtain} fill={look === 'inks' ? INK.blue : ground} stroke={ink} strokeWidth={lw(0.3)} /> : null}
      {streaks}
      {dots}
      {paper ? null : <path d={area} fill="url(#ground)" />}
      <path d={line} fill="none" stroke={ink} strokeWidth={Math.max(u * 0.7, 2.5)} strokeLinecap="round" strokeLinejoin="round" />
      {marks}
      {labels}
      <line x1={left} y1={bottom} x2={right} y2={bottom} stroke={ink} strokeWidth={lw(0.2)} opacity={paper ? 1 : 0.5} />
      {nights}
      {suns}

      {round ? (
        <g>
          <text x={W / 2} y={H * 0.09} fontFamily="FiraGO" fontWeight={600} fontSize={fs(3.2)} fill={ink} opacity={paper ? 1 : 0.8} textAnchor="middle">
            {`${(weather.place || '').toUpperCase()} · NOW`}
          </text>
          <text x={W / 2} y={H * 0.19} fontFamily="FiraGO" fontWeight={paper ? 400 : 300} fontSize={u * 10} fill={ink} textAnchor="middle">
            {degrees(current.temperature)}
          </text>
          <text x={W / 2} y={H * 0.25} fontFamily="FiraGO" fontSize={fs(3.6)} fill={ink} textAnchor="middle">
            {wordsFor(current.code)}
          </text>
          <text x={W / 2} y={H * 0.91} fontFamily="FiraGO" fontSize={fs(3.2)} fill={ink} opacity={paper ? 1 : 0.8} textAnchor="middle">
            {rainText}
          </text>
        </g>
      ) : null}
      {round ? null : (
        <>
          <text x={u * 4} y={u * 6.5} fontFamily="FiraGO" fontWeight={600} fontSize={fs(3.2)} fill={ink} opacity={paper ? 1 : 0.8}>
            {`${(weather.place || '').toUpperCase()} · NOW`}
          </text>
          <text x={u * 4} y={u * 15.5} fontFamily="FiraGO" fontWeight={paper ? 400 : 300} fontSize={u * 10} fill={ink}>
            {degrees(current.temperature)}
          </text>
          <text x={u * 4 + u * 10 * 0.62 * degrees(current.temperature).length + u * 2} y={u * 15.5} fontFamily="FiraGO" fontSize={fs(4)} fill={ink}>
            {wordsFor(current.code)}
          </text>
          <text x={W - u * 4} y={u * 6.5} fontFamily="FiraGO" fontWeight={600} fontSize={fs(3.2)} fill={ink} opacity={paper ? 1 : 0.8} textAnchor="end">
            {`NEXT ${count} HOURS`}
          </text>
          <text x={W - u * 4} y={u * 6.5 + fs(3.2) * 1.4} fontFamily="FiraGO" fontSize={fs(3.2)} fill={ink} opacity={paper ? 1 : 0.8} textAnchor="end">
            {rainText}
          </text>
        </>
      )}
    </svg>
  )
}

